// 2025-1-22 00:08
// 科赫雪花
// koch Snowflake

// F+F--F+F


//////// 0 <= IterationDepth <= 5
//////// The mouse takes effect： IterationDepth < 1  
#define IterationDepth 0


#define PI 3.1415926535
#define rot(a) mat2(cos(a),-sin(a),sin(a),cos(a))

int D[] = int[](0, 1, 0,-1, -1, 0, 1, 0, // used for curves
                0,-1,-1, 0, -1,-1, 0, 1); // only used for snowflake
#define L(u, b) length(u - b * clamp(dot(b, u) / dot(b, b), 0., 1.))

void mainImage(out vec4 O, vec2 U) {
        vec2 R = iResolution.xy, p, s,
                // u = u / R.x;
                u = .6*(U + U - R) / R.y;
        O = vec4(.9,.0,0,1);
        float a = sqrt(3.)/3., b=1./3., g=length(u), o=atan(u.y,u.x),h,t;

        if(iMouse.y>R.y*.7)b*=.6+.4*sin(iTime);

        g/=b;
        g = log(g/b)/log(a/b);
        t = 2.-2.*fract(iTime*.3);
        g += t;
        h =floor(g);

        g = fract(g);
        g = pow(a/b, g);
        g*=b;

        if(int(h)%2==0)o+=PI/6.;
        o -= t*PI/6.;
        u = g * vec2( cos(o),sin(o)  );



        int c, f, i[9], y, M = IterationDepth,
                w[9];  w[0] = 1; // w[] only used for snowflake

    M = clamp(M, 0, 5);///////////////////////////////////////
    if(IterationDepth<1)
            M = 1+int(iMouse.x*5./R.x+1.)%5;

        float d = 1e8, r = pow(3., float(M));


        u.y -= sqrt(3.) / 6.;
        u.x += .5;
        u = u * r;

        //mat2 m = rot(PI/12.);

        for (;;) {
                c = D[w[y] * 8 + i[y]];
                i[y]++;
                f += c;
                if (c == 0) {
                        if (y == M) {
                                s = cos(6.28 * float(f) / 6. + vec2(0, 11)),
                                d = min(d, L(u - p, s));

                                p += s;
                        } else {
                                y++, 
                                i[y] = 0;
                        }
                }
                while (i[y] > 7) {
                        y--;
                        if (y < 0) {
                                d *= pow(a/b, h-t);
                                O.xy += .7-smoothstep(r * 20. / R.y, 0., d);
                                O = .3+.7*O;
                                return;
                        }
                }
        }
}
